const esc = (s) => String(s ?? '').replace(/[&<>"']/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));
const shell = (title, body, ctaText, ctaUrl) => `
<div style="font-family:Inter,Arial,sans-serif;max-width:560px;margin:0 auto;background:#0f1115;color:#e5e7eb;border-radius:12px;overflow:hidden">
  <div style="background:#FB923C;color:#0f1115;padding:18px 24px;font-size:20px;font-weight:700">OFAI</div>
  <div style="padding:24px">
    <h2 style="margin:0 0 12px;font-size:20px;color:#fff">${title}</h2>
    ${body}
    <p style="margin:24px 0 0"><a href="${ctaUrl}" style="background:#FB923C;color:#0f1115;text-decoration:none;padding:12px 20px;border-radius:8px;font-weight:600;display:inline-block">${ctaText}</a></p>
  </div>
  <div style="padding:14px 24px;font-size:12px;color:#9ca3af;border-top:1px solid #1f2937">Primești acest email pentru că ai un cont pe ofai.ro. <a href="https://ofai.ro/account" style="color:#9ca3af">Preferințe</a></div>
</div>`;
// Un singur email per proprietar, cu toate ofertele lui care expiră.
const byOwner = new Map();
for (const { json: r } of $input.all()) {
  if (!r.owner_email) continue;
  if (!byOwner.has(r.owner_email)) byOwner.set(r.owner_email, { name: r.owner_first_name, offers: [] });
  byOwner.get(r.owner_email).offers.push(r);
}
const fmt = (d) => new Date(d).toLocaleDateString('ro-RO', { day: 'numeric', month: 'long' });
return [...byOwner.entries()].map(([email, { name, offers }]) => {
  const list = offers.map((o) => `<li><b>${esc(o.title)}</b> (${esc(o.business_name)}) – expiră pe ${fmt(o.end_date)}</li>`).join('');
  const body = `<p>Salut${name ? ', ' + esc(name) : ''}! Peste 3 zile expiră ${offers.length === 1 ? 'o ofertă' : offers.length + ' oferte'} de-ale tale:</p><ul style="line-height:1.8">${list}</ul><p>Prelungește perioada sau publică o ofertă nouă ca să rămâi vizibil.</p>`;
  return { json: { to: email, subject: offers.length === 1 ? 'O ofertă de-a ta expiră în 3 zile' : `${offers.length} oferte expiră în 3 zile`, html: shell('Oferte care expiră curând', body, 'Gestionează ofertele', 'https://ofai.ro/manage'), count: offers.length } };
});

const owners = $('Group by Owner').all();
const offers = owners.reduce((s, i) => s + i.json.count, 0);
return [{ json: { owners: owners.length, offers, date: new Date(Date.now() + 3 * 864e5).toLocaleDateString('ro-RO') } }];
